			function doSave(){
				
			    app.lookup("dmSave").setValue("GIVE_YM"         , app.lookup("dmSearch").getValue("YYYYMM") );
			    app.lookup("dmSave").setValue("CONSTT_ID"       , app.lookup("dsList").getValue(0, "USER_ID") );
			    app.lookup("dmSave").setValue("NIGHT_WORK_HR"   , app.lookup("dsList").getValue(0, "SSUM") );
			    app.lookup("dmSave").setValue("PENSN_SUM_AMT"   , app.lookup("dsList").getValue(0, "AAMT") );
			    
			    // 저장 서브미션 호출
				util.Submit.send(app, "subSave", function(pbSuccess){
					if(pbSuccess){
						doList("save");
					}
				});
			}

